package migrator

import (
	"context"
	"errors"
	"fmt"
	"go.mongodb.org/mongo-driver/mongo/options"
	"log"
	"os"
	"strings"
	"time"

	"github.com/RocketChat/filestore-migrator/rocketchat"
	"github.com/RocketChat/filestore-migrator/store"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
)

type rocketChatSetting struct {
	ID    string `bson:"_id"`
	Value string
}

// DebugMode sets debug mode on
func (m *Migrate) DebugMode() {
	m.debug = true
}

func (m *Migrate) debugLog(v ...interface{}) {
	if m.debug {
		logger(v...)
	}
}

func logger(v ...interface{}) {
	all := append([]interface{}{fmt.Sprintf("[%s]", time.Now().Format("01/02/2006 15:04:05"))}, v...)
	log.Println(all...)
}

// SetFileDelay set the delay between
func (m *Migrate) SetFileDelay(duration time.Duration) {
	m.fileDelay = duration
}

// SetStoreName that will be operating on
func (m *Migrate) SetStoreName(storeName string) error {
	if storeName != "Uploads" && storeName != "Avatars" {
		return errors.New("Invalid Store Name")
	}

	m.storeName = storeName

	if m.sourceStore != nil {
		m.sourceStore.SetTempDirectory(m.tempFileLocation + "/" + strings.ToLower(storeName))
	}

	if m.destinationStore != nil {
		m.destinationStore.SetTempDirectory(m.tempFileLocation + "/" + strings.ToLower(storeName))
	}

	return nil
}

func (m *Migrate) getFiles() ([]rocketchat.File, error) {
	if m.storeName == "" {
		return nil, errors.New("no store Name")
	}

	m.debugLog("Store: ", m.storeName)

	fileCollection := ""

	switch m.storeName {
	case "Uploads":
		fileCollection = "rocketchat_uploads"
	case "Avatars":
		fileCollection = "rocketchat_avatars"
	default:
		return nil, errors.New("Invalid store Name")
	}

	m.fileCollectionName = fileCollection

	session, err := connectDB(m.connectionString)
	if err != nil {
		return nil, err
	}

	m.session = session

	db := session.Client().Database(m.databaseName)

	settingsCollection := db.Collection("rocketchat_settings")

	var uniqueID rocketChatSetting

	if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "uniqueID"}).Decode(&uniqueID); err != nil {
		return nil, err
	}

	m.debugLog("uniqueId", uniqueID)
	m.uniqueID = uniqueID.Value

	collection := db.Collection(fileCollection)

	var files []rocketchat.File

	m.debugLog(fileCollection, m.sourceStore.StoreType()+":"+m.storeName)

	query := bson.M{"store": m.sourceStore.StoreType() + ":" + m.storeName}

	if !m.fileOffset.IsZero() {
		query["uploadedAt"] = bson.M{"$gte": m.fileOffset}
	}

	if cursor, err := collection.Find(context.TODO(), query, &options.FindOptions{Sort: bson.D{{"uploadedAt", -1}}}); err != nil {
		if errors.Is(err, mongo.ErrNoDocuments) {
			return nil, errors.New("No files found")
		}

		return nil, err
	} else {
		if err = cursor.All(context.TODO(), &files); err != nil {
			return nil, err
		}
	}

	return files, nil
}

// MigrateStore migrates a filestore between source and destination
func (m *Migrate) MigrateStore() error {
	if m.sourceStore == nil || m.destinationStore == nil {
		return errors.New("For MigrateStore both a source and destionation store must be provided")
	}

	files, err := m.getFiles()
	if err != nil {
		return err
	}

	m.debugLog(fmt.Sprintf("Found %v files\n", len(files)))

	for i, file := range files {
		index := i + 1 // for logs

		if m.storeName == "Avatars" && file.Rid != "" {
			// https://github.com/RocketChat/Rocket.Chat/blob/a7823c1b0901c510af5bfa994e7b3f96ee10dd91/apps/meteor/app/file-upload/server/lib/FileUpload.ts#L81-L84
			file.IsRoomAvatar = true
		}

		m.debugLog(fmt.Sprintf("[%v/%v] Downloading %s from: %s\n", index, len(files), file.Name, m.sourceStore.StoreType()))

		if !file.Complete {
			m.debugLog(fmt.Sprintf("[%v/%v] File wasn't completed uploading for %s Skipping\n", index, len(files), file.Name))
			continue
		}

		downloadedPath, err := m.sourceStore.Download(m.fileCollectionName, file)
		if err != nil {
			if errors.Is(err, store.ErrNotFound) || m.skipErrors {
				logger(fmt.Sprintf("[%v/%v] Error downloading %s (skipping): %v\n", index, len(files), file.Name, err))
				continue
			}
			return err
		}

		if file.Rid == "" && m.storeName == "Uploads" {
			file.Rid = "undefined"
		}

		if file.UserID == "" {
			file.UserID = "undefined"
		}

		objectPath := m.getObjectPath(&file)

		m.debugLog(fmt.Sprintf("[%v/%v] Uploading to %s to: %s\n", index, len(files), m.destinationStore.StoreType(), objectPath))

		if err := m.destinationStore.Upload(objectPath, downloadedPath, file.Type); err != nil {
			return err
		}

		set, unset := m.fixFileForUpload(&file, objectPath)

		update := bson.M{
			"$set": set,
		}

		if unset != "" {
			update["$unset"] = bson.M{unset: 1}
		}

		db := m.session.Client().Database(m.databaseName)
		collection := db.Collection(m.fileCollectionName)

		if _, err := collection.UpdateOne(context.TODO(), bson.M{"_id": file.ID}, update); err != nil {
			return err
		}

		m.debugLog(fmt.Sprintf("[%v/%v] Completed Uploading %s\n", index, len(files), file.Name))

		time.Sleep(m.fileDelay)

	}

	m.debugLog("Finished!")

	return nil
}

func (m *Migrate) getObjectPath(file *rocketchat.File) string {
	objectPath := ""

	switch m.storeName {
	case "Uploads":
		// https://github.com/RocketChat/Rocket.Chat/blob/a7823c1b0901c510af5bfa994e7b3f96ee10dd91/apps/meteor/app/file-upload/server/lib/FileUpload.ts#L58-L60
		objectPath = fmt.Sprintf("%s/%s/%s/%s/%s", m.uniqueID, strings.ToLower(m.storeName), file.Rid, file.UserID, file.ID)
	case "Avatars":
		var pathSuffix string
		if file.IsRoomAvatar {
			// https://github.com/RocketChat/Rocket.Chat/blob/a7823c1b0901c510af5bfa994e7b3f96ee10dd91/apps/meteor/app/file-upload/server/lib/FileUpload.ts#L81-L84
			pathSuffix = "room-" + file.Rid
		} else {
			pathSuffix = file.UserID
		}

		objectPath = fmt.Sprintf("%s/%s/%s", m.uniqueID, strings.ToLower(m.storeName), pathSuffix)
	}

	// FileSystem just dumps them in the folder based on the ID
	if m.destinationStore.StoreType() == "FileSystem" {
		objectPath = file.ID
	}

	return objectPath
}

func (m *Migrate) fixFileForUpload(file *rocketchat.File, objectPath string) (rocketchat.FileSetOp, string) {
	// what to unset
	unset := ""

	set := rocketchat.FileSetOp{}

	switch m.destinationStore.StoreType() {
	case "AmazonS3":
		set.AmazonS3 = &rocketchat.AmazonS3{
			Path: objectPath,
		}

		// Set to empty object so won't be saved back
		unset = "GoogleStorage"

	case "GoogleCloudStorage":
		set.GoogleStorage = &rocketchat.GoogleStorage{
			Path: objectPath,
		}

		// Set to empty object so won't be saved back
		unset = "AmazonS3"
	case "FileSystem":
	default:
	}

	ufsPath := fmt.Sprintf("/ufs/%s:%s/%s/%s", m.destinationStore.StoreType(), m.storeName, file.ID, file.Name)

	set.Url = m.siteUrl + ufsPath
	set.Path = ufsPath
	set.Store = m.destinationStore.StoreType() + ":" + m.storeName

	return set, unset
}

// SetFileOffset sets an offset for file upload/downloads
func (m *Migrate) SetFileOffset(offset time.Time) error {
	if offset.IsZero() {
		return errors.New("invalid date")
	}

	m.fileOffset = offset

	return nil
}

// DownloadAll downloads all files from a filestore
func (m *Migrate) DownloadAll() error {
	if m.sourceStore == nil {
		return errors.New("For DownloadAll must have a source store provided")
	}

	files, err := m.getFiles()
	if err != nil {
		return err
	}

	m.debugLog(fmt.Sprintf("Found %v files\n", len(files)))

	for i, file := range files {
		index := i + 1 // for logs

		m.debugLog(fmt.Sprintf("[%v/%v] Downloading %s from: %s\n", index, len(files), file.Name, m.sourceStore.StoreType()))

		if !file.Complete {
			fmt.Printf("[%v/%v] rocketchat.File wasn't completed uploading for %s Skipping\n", index, len(files), file.Name)
			continue
		}

		if _, err := m.sourceStore.Download(m.fileCollectionName, file); err != nil {
			if errors.Is(err, store.ErrNotFound) || m.skipErrors {
				logger(fmt.Sprintf("[%v/%v] Error downloading %s (skipping): %v\n", index, len(files), file.Name, err))
				continue
			}
			return err
		}

		m.debugLog(fmt.Sprintf("[%v/%v] Downloaded %s from: %s\n", index, len(files), file.Name, m.sourceStore.StoreType()))

		time.Sleep(m.fileDelay)
	}

	m.debugLog("Finished!")

	return nil
}

// UploadAll uploads all files from a filestore
func (m *Migrate) UploadAll(filesRoot string) error {
	if m.destinationStore == nil {
		return errors.New("For UploadAll must have a destination store provided")
	}

	files, err := m.getFiles()
	if err != nil {
		return err
	}

	m.debugLog(fmt.Sprintf("Found %v files in database\n", len(files)))

	filesRoot = filesRoot + "/" + strings.ToLower(m.storeName)

	for i, file := range files {
		index := i + 1 // for logs

		fileLocation := filesRoot + "/" + file.ID

		if _, err := os.Stat(fileLocation); os.IsNotExist(err) {
			log.Println("Failed to locate: ", file.Name)
			continue
		}

		m.debugLog(fmt.Sprintf("[%v/%v] Uploading %s to: %s\n", index, len(files), file.Name, m.destinationStore.StoreType()))

		if !file.Complete {
			fmt.Printf("[%v/%v] rocketchat.File wasn't completed uploading for %s Skipping\n", index, len(files), file.Name)
			continue
		}

		objectPath := m.getObjectPath(&file)

		m.debugLog(fmt.Sprintf("[%v/%v] Uploading to %s to: %s\n", index, len(files), m.destinationStore.StoreType(), objectPath))
		if err := m.destinationStore.Upload(objectPath, fileLocation, file.Type); err != nil {
			return err
		}

		set, unset := m.fixFileForUpload(&file, objectPath)

		update := bson.M{
			"$set": set,
		}

		if unset != "" {
			update["$unset"] = bson.M{unset: 1}
		}

		collection := m.session.Client().Database(m.databaseName).Collection(m.fileCollectionName)

		if _, err := collection.UpdateOne(context.TODO(), bson.M{"_id": file.ID}, update); err != nil {
			return err
		}

		m.debugLog(fmt.Sprintf("[%v/%v] Completed Uploading %s\n", index, len(files), file.Name))

		time.Sleep(m.fileDelay)
	}

	m.debugLog("Finished!")

	return nil
}

package migrator

import (
	"context"
	"errors"
	"log"
	"os"
	"strings"
	"time"

	"github.com/RocketChat/filestore-migrator/config"
	"github.com/RocketChat/filestore-migrator/store"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/gridfs"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// Migrate needs to be initialized to begin any migration
type Migrate struct {
	siteUrl            string
	storeName          string
	skipErrors         bool
	sourceStore        store.Provider
	destinationStore   store.Provider
	databaseName       string
	connectionString   string
	fileCollectionName string
	fileOffset         time.Time
	session            mongo.Session
	uniqueID           string
	tempFileLocation   string
	fileDelay          time.Duration
	debug              bool
}

type settingValue struct {
	Value string `bson:"value"`
}

// New takes the config and returns an initialized Migrate ready to begin migrations
func New(config *config.Config, skipErrors bool) (*Migrate, error) {

	if config.Database.ConnectionString == "" {
		return nil, errors.New("Missing connectionString for Rocket.Chat's Mongo")
	}

	if config.Database.Database == "" {
		return nil, errors.New("Missing db for Rocket.Chat's DB")
	}

	if config.TempFileLocation == "" {
		config.TempFileLocation = "files"
	}

	config.TempFileLocation = strings.TrimSuffix(config.TempFileLocation, "/")

	fileDelay := time.Millisecond * 10

	if config.FileDelay != "" {
		delay, err := time.ParseDuration(config.FileDelay)
		if err != nil {
			log.Println("invalid fileDelay value")
			return nil, err
		}

		fileDelay = delay
	}

	s, err := connectDB(config.Database.ConnectionString)
	if err != nil {
		return nil, err
	}

	value := &settingValue{}
	err = s.Client().Database(config.Database.Database).Collection("rocketchat_settings").FindOne(context.Background(), bson.M{"_id": "Site_Url"}).Decode(value)
	if err != nil {
		return nil, err
	}

	migrate := &Migrate{
		siteUrl:          strings.TrimSuffix(value.Value, "/"),
		skipErrors:       skipErrors,
		databaseName:     config.Database.Database,
		connectionString: config.Database.ConnectionString,
		tempFileLocation: config.TempFileLocation,
		fileDelay:        fileDelay,
		debug:            config.DebugMode,
	}

	if _, err := os.Stat(config.TempFileLocation + "/uploads"); os.IsNotExist(err) {
		if err := os.MkdirAll(config.TempFileLocation+"/uploads", 0777); err != nil {
			migrate.debugLog(err)
			return nil, errors.New("Temp Directory doesn't exist and unable to create it")
		}
	}

	if _, err := os.Stat(config.TempFileLocation + "/avatars"); os.IsNotExist(err) {
		if err := os.MkdirAll(config.TempFileLocation+"/avatars", 0777); err != nil {
			migrate.debugLog(err)
			return nil, errors.New("Temp Directory doesn't exist and unable to create it")
		}
	}

	if config.Source.Type != "" {

		switch config.Source.Type {
		case "GridFS":
			session, err := connectDB(config.Database.ConnectionString)
			if err != nil {
				return nil, err
			}

			sourceStore := &store.GridFSProvider{
				Database:         config.Database.Database,
				Session:          session,
				TempFileLocation: config.TempFileLocation,
				Buckets:          make(map[string]*gridfs.Bucket),
			}

			migrate.sourceStore = sourceStore

		case "GoogleStorage":
			if (config.Source.GoogleStorage.Bucket == "" || config.Source.GoogleStorage.JSONKey == "") && !config.Source.ReferenceOnly {
				return nil, errors.New("Make sure you include all of the required options for GoogleStorage")
			}

			sourceStore := &store.GoogleStorageProvider{
				JSONKey:          config.Source.GoogleStorage.JSONKey,
				Bucket:           config.Source.GoogleStorage.Bucket,
				TempFileLocation: config.TempFileLocation,
			}

			migrate.sourceStore = sourceStore
		case "AmazonS3":
			if (config.Source.AmazonS3.AccessID == "" || config.Source.AmazonS3.AccessKey == "" || config.Source.AmazonS3.Bucket == "") && !config.Source.ReferenceOnly {
				return nil, errors.New("Make sure you include all of the required options for AmazonS3")
			}

			sourceStore := &store.S3Provider{
				Endpoint:         config.Source.AmazonS3.Endpoint,
				AccessID:         config.Source.AmazonS3.AccessID,
				AccessKey:        config.Source.AmazonS3.AccessKey,
				Region:           config.Source.AmazonS3.Region,
				Bucket:           config.Source.AmazonS3.Bucket,
				UseSSL:           config.Source.AmazonS3.UseSSL,
				TempFileLocation: config.TempFileLocation,
			}

			migrate.sourceStore = sourceStore
		case "FileSystem":
			if config.Source.FileSystem.Location == "" && !config.Source.ReferenceOnly {
				return nil, errors.New("Make sure you include all of the required options for FileSystem")
			}

			config.Source.FileSystem.Location = strings.TrimSuffix(config.Source.FileSystem.Location, "/")

			if !config.Source.ReferenceOnly {
				if _, err := os.Stat(config.Source.FileSystem.Location); os.IsNotExist(err) {
					return nil, errors.New("Filesystem source location does not exist or is unaccessible")
				}
			}

			sourceStore := &store.FileSystemStorageProvider{
				Location:         config.Source.FileSystem.Location,
				TempFileLocation: config.TempFileLocation,
			}

			migrate.sourceStore = sourceStore
		default:
			return nil, errors.New("Invalid Source Type")
		}

		migrate.debugLog("Source store type set to: ", config.Source.Type)
	}

	if config.Destination.Type != "" {

		switch config.Destination.Type {
		case "AmazonS3":
			if config.Destination.AmazonS3.AccessID == "" || config.Destination.AmazonS3.AccessKey == "" || config.Destination.AmazonS3.Bucket == "" {
				return nil, errors.New("Make sure you include all of the required options for AmazonS3")
			}

			destinationStore := &store.S3Provider{
				Endpoint:  config.Destination.AmazonS3.Endpoint,
				AccessID:  config.Destination.AmazonS3.AccessID,
				AccessKey: config.Destination.AmazonS3.AccessKey,
				Region:    config.Destination.AmazonS3.Region,
				Bucket:    config.Destination.AmazonS3.Bucket,
				UseSSL:    config.Destination.AmazonS3.UseSSL,
			}

			migrate.destinationStore = destinationStore

		case "GoogleStorage":
			if config.Destination.GoogleStorage.Bucket == "" || config.Destination.GoogleStorage.JSONKey == "" {
				return nil, errors.New("Make sure you include all of the required options for AmazonS3")
			}

			destinationStore := &store.GoogleStorageProvider{
				JSONKey: config.Destination.GoogleStorage.JSONKey,
				Bucket:  config.Destination.GoogleStorage.Bucket,
			}

			migrate.destinationStore = destinationStore
		case "FileSystem":
			if config.Destination.FileSystem.Location == "" {
				return nil, errors.New("Make sure you include all of the required options for FileSystem")
			}

			if _, err := os.Stat(config.Destination.FileSystem.Location); os.IsNotExist(err) {
				if err := os.MkdirAll(config.Destination.FileSystem.Location, 0777); err != nil {
					migrate.debugLog(err)
					return nil, errors.New("filesystem directory doesn't exist and unable to create it")
				}
			}

			destinationStore := &store.FileSystemStorageProvider{
				Location: config.Destination.FileSystem.Location,
			}

			migrate.destinationStore = destinationStore
		default:
			return nil, errors.New("Invalid Destination Type")
		}

		migrate.debugLog("Destination store type set to: ", config.Destination.Type)

	}

	if migrate.sourceStore == nil && migrate.destinationStore == nil {
		return nil, errors.New("At least a source or destination store must be provided")
	}

	return migrate, nil
}

var ErrNoJsonKey = errors.New("no-json-key")

// GetRocketChatStore uses database to build source Store from settings
func GetRocketChatStore(dbConfig config.DatabaseConfig) (*config.MigrateTarget, error) {
	session, err := connectDB(dbConfig.ConnectionString)
	if err != nil {
		return nil, err
	}

	defer session.EndSession(context.TODO())

	client := session.Client()

	db := client.Database(dbConfig.Database)

	settingsCollection := db.Collection("rocketchat_settings")

	var fileUploadStorageType rocketChatSetting

	if err = settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_Storage_Type"}).Decode(&fileUploadStorageType); err != nil {
		return nil, err
	}

	sourceStore := &config.MigrateTarget{}

	switch fileUploadStorageType.Value {
	case "GridFS":
		sourceStore.Type = "GridFS"
		return sourceStore, nil
	case "AmazonS3":
		sourceStore.Type = "AmazonS3"
		var awsAccessID rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_S3_AWSAccessKeyId"}).Decode(&awsAccessID); err != nil {
			return nil, err
		}

		var awsSecret rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_S3_AWSSecretAccessKey"}).Decode(&awsSecret); err != nil {
			return nil, err
		}

		var bucket rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_S3_Bucket"}).Decode(&bucket); err != nil {
			return nil, err
		}

		var region rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_S3_Region"}).Decode(&region); err != nil {
			return nil, err
		}

		var s3url rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_S3_BucketURL"}).Decode(&s3url); err != nil {
			return nil, err
		}

		if s3url.Value == "" {
			s3url.Value = "s3.amazonaws.com"
		}

		sourceStore.AmazonS3.Endpoint = s3url.Value
		sourceStore.AmazonS3.Bucket = bucket.Value
		sourceStore.AmazonS3.AccessID = awsAccessID.Value
		sourceStore.AmazonS3.AccessKey = awsSecret.Value
		sourceStore.AmazonS3.Region = region.Value
		sourceStore.AmazonS3.UseSSL = true

		return sourceStore, nil

	case "GoogleCloudStorage":
		sourceStore.Type = "GoogleStorage"

		var settingValue rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_GoogleStorage_Bucket"}).Decode(&settingValue); err != nil {
			return nil, err
		}

		sourceStore.GoogleStorage.Bucket = settingValue.Value

		//this is a weird one
		// currently a workaround, that asks for a json key file to be downloaded first
		// returns an error but appropriate consumer should catch and fix
		return sourceStore, ErrNoJsonKey

	case "FileSystem":
		sourceStore.Type = "FileSystem"
		var filesystemLocation rocketChatSetting

		if err := settingsCollection.FindOne(context.TODO(), bson.M{"_id": "FileUpload_FileSystemPath"}).Decode(&filesystemLocation); err != nil {
			return nil, err
		}

		sourceStore.FileSystem.Location = filesystemLocation.Value
		return sourceStore, nil

	default:
		return nil, errors.New("unable to detect supported fileupload storage type.  (Unable to detect google storage currently)")
	}
}

func connectDB(connectionstring string) (mongo.Session, error) {
	client, err := mongo.Connect(context.Background(), options.Client().ApplyURI(connectionstring))
	if err != nil {
		panic(err)
	}
	sess, err := client.StartSession(&options.SessionOptions{})
	if err != nil {
		return nil, err
	}

	return sess, nil
}

package store

import (
	"errors"
	"io"
	"os"

	"github.com/RocketChat/filestore-migrator/rocketchat"
)

// FileSystemStorageProvider provides methods to use the local file system as a storage provider.
type FileSystemStorageProvider struct {
	Location         string
	TempFileLocation string
}

// StoreType returns the name of the store
func (f *FileSystemStorageProvider) StoreType() string {
	return "FileSystem"
}

// SetTempDirectory allows for the setting of the directory that will be used for temporary file store during operations
func (f *FileSystemStorageProvider) SetTempDirectory(dir string) {
	f.TempFileLocation = dir
}

// Download downloads a file from the storage provider and moves it to the temporary file store
func (f *FileSystemStorageProvider) Download(fileCollection string, file rocketchat.File) (string, error) {
	sourcePath := f.Location + "/" + file.ID
	destinationPath := f.TempFileLocation + "/" + file.ID

	if _, err := os.Stat(sourcePath); os.IsNotExist(err) {
		return "", ErrNotFound
	}

	sF, err := os.Open(sourcePath)
	if err != nil {
		return "", err
	}

	defer sF.Close()

	dF, err := os.Create(destinationPath)
	if err != nil {
